function demoMain(idx,label){
  var queries=[["SELECT * FROM users",1200,1],["SELECT id FROM orders WHERE total>100",45,0],["SELECT * FROM logs JOIN users",2300,1]];
  var q=queries[idx%queries.length];
  var advice=q[2]?"ADD INDEX / avoid SELECT *":"plan OK";
  return "["+label+"] query '"+q[0]+"' took "+q[1]+"ms (seqscan="+!!q[2]+") => "+advice;
}

